WITH w AS (SELECT b.mktcode,b.tgtcode,b.bizdate,b.lastPx/10000.0 AS px,t.ma30,LAG(b.lastPx/10000.0) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate) AS ppx,LAG(t.ma30) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate) AS pma FROM `newzl`.`hsj_stock_hq_basic` AS b LEFT JOIN `newzl`.`hsj_stock_hq_basic_technical` AS t ON t.mktcode=b.mktcode AND t.tgtcode=b.tgtcode AND t.bizdate=b.bizdate) SELECT mktcode,tgtcode,bizdate FROM w WHERE bizdate='2026-04-14' AND px<ma30 AND ppx>=pma;
